  const momentsTabCss = `.pf-wechat-tabs{display:flex;flex:0 0 45px;border-top:1px solid #efd7c5;background:#fffaf3}.pf-wtab{flex:1;border:0;background:transparent;color:#b38a75;font:10px "Microsoft YaHei",sans-serif;cursor:pointer}.pf-wtab.active{color:#d98272;font-weight:800}.pf-wtab i{display:block;margin:4px auto 1px;font-size:16px;font-style:normal;line-height:16px}.pf-moment-plus{display:grid;width:27px;height:27px;place-items:center;padding:0;border:0;border-radius:50%;background:#e79b8b;color:#fff;font:22px/1 sans-serif;cursor:pointer}.pf-moment-compose-page{padding:12px}.pf-moment-compose-page textarea{display:block;width:100%;height:105px;padding:10px;border:1px solid #ead1c0;border-radius:10px;outline:0;resize:none;background:#fffdf9;color:#704f45;font:12px/1.45 "Microsoft YaHei",sans-serif}.pf-moment-compose-buttons{display:flex;justify-content:flex-end;gap:7px;margin-top:9px}.pf-moment-publish{height:29px;padding:0 11px;border:0;border-radius:99px;background:#e79b8b;color:#fff;font:10px "Microsoft YaHei",sans-serif;cursor:pointer}.pf-moment-idea{color:#a57a69;background:#f8e7dc}.pf-moment-hint{margin:0 0 8px;color:#aa7b68;font-size:10px}`;
  const derivativeCss = `.pfphone-screen{height:calc(100% - 54px)}.pfphone-homebar{margin:2px auto 0}.pf-title{max-width:148px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pf-moment-image{margin:5px 0;padding:6px 7px;border-radius:6px;background:#f7e8d9;color:#aa7b68;font-size:10px}.pf-moment-replies{margin-top:6px;padding:4px 6px;border-radius:5px;background:#f7ede5;color:#8d6658;font-size:9px;line-height:1.55}.pf-moment-replies span{display:block}.pf-model-picker{height:104px!important;padding:3px!important;font-size:10px!important}.pf-model-picker option{padding:3px 5px}`;

  function getConfig() {
    try {
      const config = { ...defaultConfig, ...JSON.parse(PWin.localStorage.getItem(CONFIG_KEY) || '{}') };
      const depth = Number(config.injectionDepth);
      config.injectionDepth = String(config.injectionDepth).trim() !== '' && Number.isInteger(depth) && depth >= 0 && depth <= 999 ? depth : 4;
      // 清理旧版默认提示词内固定日期、固定人物的完整示例；保留用户其他编辑。
      config.derivativePrompt = String(config.derivativePrompt || defaultConfig.derivativePrompt).replace(/\s*完整示例：\s*<status>\s*时间：2026年4月16日 18:40[\s\S]*?知晓青空之蓝之人回复无敌霸王龙：就在附近，晚点回。\s*<\/moments>/, '');
      // 已保存旧默认提示词的用户也获得本次更新；只替换完整匹配的旧任务段。
      const previousTask = [
        '任务：阅读本轮正剧、此前手机内容与当前状态，为本轮正剧生成配套的手机衍生内容。',
        '- 必须先输出且只输出一组 <status>。',
        '- 随后输出 1～2 个内容模块：<phone> 和 / 或 <moments>。',
        '- 内容应补充角色近况、关系变化、伏笔或剧情余波；不得改写既定事实、凭空推进关键主线、替玩家作决定。',
        '- 延续此前手机内容中的称呼、关系、事件进度，不要重复已有信息。',
        '- 只输出规定格式，不要解释、标题、Markdown、代码块或正剧叙述；文本字段中不要使用尖括号。',
      ].join('\n');
      const updatedTask = defaultConfig.derivativePrompt.slice(defaultConfig.derivativePrompt.indexOf('任务：'), defaultConfig.derivativePrompt.indexOf('\n\n格式：'));
      const previousLatestTask = [
        '任务：阅读剧情、此前手机内容与当前状态，为目前为止最新的时间节点生成此时配套的手机衍生内容。',
        '- 必须先输出且只输出一组 <status>。',
        '- 随后输出 1～2 个内容模块：<phone> 和 / 或 <moments>。',
        '- 内容可以补充角色近况、关系变化、伏笔或剧情余波；不得改写既定事实、凭空推进关键主线、替{{user}}写{{user}}自己的发言。',
        '- 内容代表当前剧情中，{{user}}的手机里的内容，所以应配合当前最新情节，注意逻辑；例如如果{{user}}目前和某角色正待在一起，那么他们这会不太可能进行手机联络。',
        '- 仅输出规定格式，不要解释、标题、Markdown、代码块或正剧叙述。',
      ].join('\n');
      if (!config.derivativePromptCustomized) {
        config.derivativePrompt = config.derivativePrompt.replace(/\r\n/g, '\n').replace(previousTask, updatedTask).replace(previousLatestTask, updatedTask);
        const priorDefault = defaultConfig.derivativePrompt.replace(`\n\n${AUTO_STATUS_GUIDANCE}`, '').trim();
        if (config.derivativePrompt.trim() === priorDefault) config.derivativePrompt = defaultConfig.derivativePrompt;
      }
      return config;
    }
    catch (_) { return { ...defaultConfig }; }
  }
  function saveConfig(config) { PWin.localStorage.setItem(CONFIG_KEY, JSON.stringify({ ...defaultConfig, ...config })); }
  function currentChatId() {
    const candidates = [
      () => ST && ST.getCurrentChatId && ST.getCurrentChatId(),
      () => typeof SillyTavern !== 'undefined' && SillyTavern && SillyTavern.getCurrentChatId && SillyTavern.getCurrentChatId(),
      () => PWin.SillyTavern && PWin.SillyTavern.getCurrentChatId && PWin.SillyTavern.getCurrentChatId(),
      () => { const getId = helper('getCurrentChatId'); return getId && getId(); },
      () => PWin.chatId,
      () => typeof chatId !== 'undefined' && chatId,
    ];
    for (const getId of candidates) {
      try {
        const id = getId();
        if (id != null && String(id).trim()) return String(id).trim();
      } catch (_) {}
    }
    return 'default';
  }
  function currentChatScope() { return CHAT_KEY_PREFIX + currentChatId(); }
  function chatStorageKey() { return currentChatScope(); }
  function scopedKey(prefix) { return prefix + currentChatScope().slice(CHAT_KEY_PREFIX.length); }
  function chatVariableApi() {
    try {
      const th = (typeof TavernHelper !== 'undefined' && TavernHelper) || PWin.TavernHelper;
      return th && typeof th.getVariables === 'function' && typeof th.insertOrAssignVariables === 'function' ? th : null;
    } catch (_) { return null; }
  }
  function readLegacyJson(key, fallback) {
    try { return JSON.parse(PWin.localStorage.getItem(key) || '') || fallback; }
    catch (_) { return fallback; }
  }
  function readLegacyPhoneData() {
    const data = {
      chats: readLegacyJson(chatStorageKey(), {}),
      moments: readLegacyJson(scopedKey(MOMENT_KEY_PREFIX), []),
      derivativeHistory: readLegacyJson(scopedKey(DERIVATIVE_HISTORY_KEY_PREFIX), []),
      status: readLegacyJson(scopedKey(STATUS_KEY_PREFIX), {}),
      dynamicContacts: readLegacyJson(scopedKey(DYNAMIC_CONTACT_KEY_PREFIX), {}),
      autoFloor: String(PWin.localStorage.getItem(scopedKey(AUTO_FLOOR_KEY_PREFIX)) || ''),
      resetEpoch: String(PWin.localStorage.getItem(scopedKey('floating_phone_reset_epoch_v1:')) || ''),
    };
    const hasData = Object.keys(data.chats).length || data.moments.length || data.derivativeHistory.length
      || Object.keys(data.status).length || Object.keys(data.dynamicContacts).length || data.autoFloor || data.resetEpoch;
    return hasData ? data : null;
  }
  function getPhoneData() {
    const api = chatVariableApi();
    if (api) {
      try {
        const variables = api.getVariables({ type: 'chat' }) || {};
        const stored = variables[CHAT_DATA_VAR];
        if (stored && typeof stored === 'object' && !Array.isArray(stored)) return cleanSeedPhoneData(stored);
        const legacy = readLegacyPhoneData();
        if (legacy) { const cleaned = cleanSeedPhoneData(legacy); api.insertOrAssignVariables({ [CHAT_DATA_VAR]: cleaned }, { type: 'chat' }); return cleaned; }
        return {};
      } catch (error) { console.warn('[FloatingPhone] 读取聊天变量失败，暂时使用本地兼容存储', error); }
    }
    return cleanSeedPhoneData(readLegacyPhoneData() || {});
  }
  function cleanSeedPhoneData(original) {
    const data = { ...original, chats: { ...(original.chats || {}) }, dynamicContacts: { ...(original.dynamicContacts || {}) } };
    for (const [key, messages] of Object.entries(data.chats)) {
      if (!Array.isArray(messages)) continue;
      const seed = legacySeedContacts[key];
      const actual = messages.filter(message => !message.placeholder && !(seed && message.side === 'them' && message.time === '10:28' && message.text === seed.hello));
      if (actual.length) {
        data.chats[key] = actual;
        if (seed && !data.dynamicContacts[key]) data.dynamicContacts[key] = { title: seed.title, icon: seed.icon };
      } else delete data.chats[key];
    }
    return data;
  }
  function savePhoneData(data) {
    const api = chatVariableApi();
    if (api) {
      try { api.insertOrAssignVariables({ [CHAT_DATA_VAR]: data }, { type: 'chat' }); return; }
      catch (error) { console.warn('[FloatingPhone] 写入聊天变量失败，暂时使用本地兼容存储', error); }
    }
    PWin.localStorage.setItem(chatStorageKey(), JSON.stringify(data.chats || {}));
    PWin.localStorage.setItem(scopedKey(MOMENT_KEY_PREFIX), JSON.stringify(data.moments || []));
    PWin.localStorage.setItem(scopedKey(DERIVATIVE_HISTORY_KEY_PREFIX), JSON.stringify(data.derivativeHistory || []));
    PWin.localStorage.setItem(scopedKey(STATUS_KEY_PREFIX), JSON.stringify(data.status || {}));
    PWin.localStorage.setItem(scopedKey(DYNAMIC_CONTACT_KEY_PREFIX), JSON.stringify(data.dynamicContacts || {}));
    PWin.localStorage.setItem(scopedKey(AUTO_FLOOR_KEY_PREFIX), String(data.autoFloor || ''));
    PWin.localStorage.setItem(scopedKey('floating_phone_reset_epoch_v1:'), String(data.resetEpoch || ''));
  }
  function clearCurrentPhoneData($dialog) {
    const scope = currentChatId();
    if ($dialog.data('pfChatScope') !== scope) throw new Error('聊天文件已切换，请重新打开设置。');
    // 同时移除旧版兼容副本，防止下次读取时迁回旧数据。
    [CHAT_KEY_PREFIX, MOMENT_KEY_PREFIX, DERIVATIVE_HISTORY_KEY_PREFIX, STATUS_KEY_PREFIX, DYNAMIC_CONTACT_KEY_PREFIX, AUTO_FLOOR_KEY_PREFIX].forEach(prefix => PWin.localStorage.removeItem(scopedKey(prefix)));
    savePhoneData({ chats: {}, moments: [], status: {}, dynamicContacts: {}, derivativeHistory: [], autoFloor: '', resetEpoch: `${Date.now()}_${Math.random().toString(36).slice(2)}` });
    clearPhoneInjection();
    phoneViewStates.delete(scope);
    $dialog.removeData('pfInboxScroll');
  }
  function getChats() {
    const chats = getPhoneData().chats;
    return chats && typeof chats === 'object' && !Array.isArray(chats) ? chats : {};
  }
  function saveChats(chats) { const data = getPhoneData(); data.chats = chats || {}; savePhoneData(data); }
  function getDynamicContacts() {
    const contactsData = getPhoneData().dynamicContacts;
    return contactsData && typeof contactsData === 'object' && !Array.isArray(contactsData) ? contactsData : {};
  }
  function getContacts() { return getDynamicContacts(); }
  function contactFor(key) { return getContacts()[key] || { title: '未知联系人', icon: '💬' }; }
  function groupMembers(contact) {
    const all = getContacts();
    return (contact.members || []).filter(key => all[key] && all[key].type !== 'group').map(key => ({ key, ...all[key] }));
  }
  function contactKeyForName(name) {
    const title = String(name || '').trim() || '未知联系人';
    const all = getContacts();
    const existing = Object.keys(all).find(key => all[key] && all[key].title === title);
    if (existing) return existing;
    const key = `chat_${encodeURIComponent(title)}`;
    const dynamic = getDynamicContacts();
    dynamic[key] = { title, icon: '💬', hello: ' ' };
    const data = getPhoneData(); data.dynamicContacts = dynamic; savePhoneData(data);
    return key;
  }
  function getMoments() {
    const moments = getPhoneData().moments;
    return Array.isArray(moments) ? moments : [];
  }
  function addMoment(moment) {
    const data = getPhoneData(); data.moments = Array.isArray(data.moments) ? data.moments : [];
    data.moments.push(stampPhoneEntry(moment)); savePhoneData(data);
  }
  function messagesFor(key) {
    const chats = getChats();
    return Array.isArray(chats[key]) ? chats[key] : [];
  }
  function addMessage(key, message) {
    const chats = getChats();
    chats[key] = Array.isArray(chats[key]) ? chats[key] : [];
    const saved = { ...stampPhoneEntry(message), id: `${Date.now()}_${Math.random().toString(36).slice(2)}` };
    saved.receivedAt = Date.now();
    const active = phonePopup && phonePopup.isConnected ? $(phonePopup) : null;
    const route = active && active.data('pfViewRoute');
    saved.unread = message.side !== 'self' && !message.placeholder && !(active && active.data('pfChatScope') === currentChatId() && route?.page === 'chat' && route.key === key);
    chats[key].push(saved);
    saveChats(chats);
    scheduleInboxRefresh();
    return saved;
  }
  function getStatus() {
    const status = getPhoneData().status;
    return status && typeof status === 'object' && !Array.isArray(status) ? status : {};
  }
  function saveStatus(status) { const data = getPhoneData(); data.status = status || {}; savePhoneData(data); }
  function clock() { return String(getStatus().time || '').trim(); }

  // 剧情日期按同一无时区时间轴计算；绝不把剧情日期与现实日期相减。
  function parsePhoneDate(value) {
    const match = String(value || '').trim().match(/^(\d{4})[年/.-](\d{1,2})[月/.-](\d{1,2})日?(?:[ T\s]+([01]?\d|2[0-3])[:：]([0-5]\d)(?:[:：]([0-5]\d))?)?/);
    if (!match) return null;
    const [, y, m, d, h = '0', minute = '0', second = '0'] = match;
    const timestamp = Date.UTC(+y, +m - 1, +d, +h, +minute, +second);
    const date = new Date(timestamp);
    if (date.getUTCFullYear() !== +y || date.getUTCMonth() !== +m - 1 || date.getUTCDate() !== +d) return null;
    return timestamp;
  }
  function phoneNow() {
    const story = String(getStatus().time || '').trim();
    return story ? { timeline: 'story', timestamp: parsePhoneDate(story), label: story }
      : { timeline: 'story', timestamp: null, label: '' };
  }
  function stampPhoneEntry(entry) {
    const now = phoneNow();
    return { ...entry, recordedTime: now.label, timestamp: now.timestamp, timeline: now.timeline };
  }
  function phoneXml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' }[char]));
  }
  function buildPhoneInfo() {
    const now = phoneNow();
    const recent = message => {
      if (message.placeholder) return false;
      const timestamp = Number.isFinite(message.timestamp) ? message.timestamp : parsePhoneDate(message.recordedTime || message.time);
      const timeline = message.timeline || 'story';
      return timestamp === null || now.timestamp === null || timeline !== now.timeline || now.timestamp - timestamp <= 7 * 86400000;
    };
    const chats = Object.entries(getChats()).map(([key, messages]) => {
      if (!Array.isArray(messages)) return '';
      const selected = messages.slice(-10).filter(recent);
      const contact = contactFor(key);
      if (!selected.length) return '';
      return `<chat contact="${phoneXml(contact.title)}" type="${contact.type === 'group' ? 'group' : 'private'}">\n${contact.type === 'group' ? `<members>{{user}}、${groupMembers(contact).map(member => phoneXml(member.title)).join('、')}</members>\n` : ''}${selected.map(message => `<message sender="${phoneXml(message.side === 'self' ? '{{user}}' : message.sender || contact.title)}" time="${phoneXml(message.recordedTime || message.time)}">${phoneXml(message.text)}</message>`).join('\n')}\n</chat>`;
    }).filter(Boolean);
    const moments = getMoments().slice(-3).map(moment => `<moment author="${phoneXml(moment.author)}" time="${phoneXml(moment.recordedTime || moment.time)}">\n<content>${phoneXml(moment.content || moment.text)}</content>${moment.image ? `\n<image>${phoneXml(moment.image)}</image>` : ''}${moment.likes ? `\n<likes>${phoneXml(moment.likes)}</likes>` : ''}${Array.isArray(moment.replies) && moment.replies.length ? `\n<replies>${moment.replies.map(reply => `<reply>${phoneXml(reply)}</reply>`).join('')}</replies>` : ''}\n</moment>`);
    if (!chats.length && !moments.length) return '';
    const status = getStatus();
    return `<phone_info>\n这里是{{user}}目前手机里的动态信息：\n<status time="${phoneXml(now.label)}" weather="${phoneXml(status.weather)}" temperature="${phoneXml(status.temperature)}" />\n<messages>\n${chats.join('\n')}\n</messages>\n<moments>\n${moments.join('\n')}\n</moments>\n</phone_info>`;
  }
  function clearPhoneInjection() {
    const remove = removePhoneInjection;
    removePhoneInjection = null;
    try { if (remove) remove(); } catch (error) { console.warn('[FloatingPhone] 注入回调清理失败', error); }
    try { if (uninjectPhonePrompts) uninjectPhonePrompts([PHONE_INJECTION_ID]); }
    catch (error) { console.warn('[FloatingPhone] 移除手机注入失败', error); }
  }
  function refreshPhoneInjection() {
    if (!phoneScriptActive()) return;
    clearPhoneInjection();
    const content = buildPhoneInfo();
    const inject = helper('injectPrompts');
    if (!content) return;
    if (!inject) { console.warn('[FloatingPhone] 未找到 injectPrompts，手机内容无法注入正文'); return; }
    const result = inject([{ id: PHONE_INJECTION_ID, position: 'in_chat', depth: getConfig().injectionDepth, role: 'system', content, should_scan: false, filter: () => phoneScriptActive() && phoneApiRequests === 0 }]);
    if (result && typeof result.uninject === 'function') removePhoneInjection = result.uninject;
  }
  function bindPhoneInjection() {
    const on = helper('eventOn');
    const events = PWin.tavern_events || (typeof tavern_events !== 'undefined' ? tavern_events : null);
    if (!on || !events) return;
    const bind = (event, callback) => {
      if (!event) return;
      const handle = on(event, callback);
      if (handle && typeof handle.stop === 'function') autoEventStops.push(() => handle.stop());
    };
    bind(events.GENERATION_AFTER_COMMANDS, () => { if (!phoneApiRequests) refreshPhoneInjection(); });
    bind(events.CHAT_CHANGED, clearPhoneInjection);
  }
  async function runPhoneGeneration(generate, config) {
    if (!phoneScriptActive()) throw new Error('小手机脚本已关闭');
    const scope = currentChatId();
    const resetEpoch = getPhoneData().resetEpoch || '';
    phoneApiRequests += 1;
    try {
      const result = await generate(config);
      if (!phoneScriptActive()) throw new Error('小手机脚本已关闭');
      if (currentChatId() !== scope || (getPhoneData().resetEpoch || '') !== resetEpoch) throw new Error('聊天已切换或手机数据已清空，本次旧回复已忽略');
      return result;
    }
    finally { phoneApiRequests -= 1; }
  }

  // 不使用显示正则。每层仅按 prompt 目的处理，正好复用“远楼正文 -> 摘要”的压缩规则。
  function buildRegexedHistory() {
    const getMessages = helper('getChatMessages');
    const formatRegex = helper('formatAsTavernRegexedString');
    if (!getMessages || !formatRegex) throw new Error('未找到酒馆助手的聊天记录或正则接口');
    // 发送时读取真实末楼，不依赖宏展开时机；范围包含该末楼。
    const latest = getMessages(-1, { hide_state: 'all' })[0];
    if (!latest) return [];
    const lastId = Number(latest.message_id);
    if (!Number.isInteger(lastId) || lastId < 0) throw new Error('无法读取正文最新楼层号');
    const messages = getMessages(`0-${lastId}`, { hide_state: 'unhidden' });
    return messages
      .filter(message => message && typeof message.message === 'string')
      .map((message, index, all) => ({
        role: message.role === 'assistant' ? 'assistant' : message.role === 'system' ? 'system' : 'user',
        content: formatRegex(
          message.message,
          message.role === 'assistant' ? 'ai_output' : 'user_input',
          'prompt',
          { depth: Number.isInteger(message.message_id) ? lastId - message.message_id : all.length - 1 - index },
        ),
      }));
  }

  function getDerivativeHistory() {
    const history = getPhoneData().derivativeHistory;
    return Array.isArray(history) ? history : [];
  }
  function saveDerivativeHistory(history) { const data = getPhoneData(); data.derivativeHistory = (history || []).slice(-30); savePhoneData(data); }
  function addDerivativeHistory(raw) {
    const history = getDerivativeHistory();
    history.push({ raw: String(raw || '').trim(), time: Date.now() });
    saveDerivativeHistory(history);
  }
  function mainContentForDerivative() {
    return buildRegexedHistory().map(message => `[${message.role}]\n${message.content}`).join('\n\n');
  }
  // 即便副 API 漏写闭合标签，也将区块读取到下一个顶层标签或文本末尾，避免整轮内容报废。
  function extractTopLevelBlocks(raw, tag) {
    const source = String(raw || ''); const blocks = [];
    const open = new RegExp(`<${tag}\\b[^>]*>`, 'gi'); let match;
    while ((match = open.exec(source))) {
      const start = open.lastIndex;
      const close = new RegExp(`</${tag}\\s*>`, 'ig'); close.lastIndex = start;
      const closing = close.exec(source);
      const next = /<(?:status|phone|moments)\b[^>]*>/ig; next.lastIndex = start;
      const nextMatch = next.exec(source);
      let end = source.length;
      if (closing) end = Math.min(end, closing.index);
      if (nextMatch) end = Math.min(end, nextMatch.index);
      blocks.push(source.slice(start, end).trim());
      open.lastIndex = closing && closing.index < end + 1 ? close.lastIndex : Math.max(open.lastIndex, end);
    }
    return blocks.filter(Boolean);
  }
  function parseStatusBlock(block) {
    const status = {};
    String(block || '').split(/\r?\n/).forEach(line => {
      const match = line.trim().match(/^(时间|天气|温度)\s*[：:]\s*(.+?)\s*$/);
      if (!match) return;
      const field = { 时间: 'time', 天气: 'weather', 温度: 'temperature' }[match[1]];
      if (field) status[field] = match[2];
    });
    return status;
  }
  function parsePhoneBlocks(blocks, time) {
    const created = [];
    blocks.forEach(block => {
      let key = null;
      String(block).split(/\r?\n/).forEach(rawLine => {
        const line = rawLine.trim(); if (!line) return;
        const heading = line.match(/^【\s*聊天\s*[：:]\s*(.+?)\s*】$/);
        if (heading) { key = contactKeyForName(heading[1]); return; }
        if (!key) return;
        const message = line.match(/^([^：:]{1,50})[：:]\s*(.+)$/);
        if (!message) return;
        const sender = message[1].trim();
        const contact = contactFor(key);
        if (contact.type === 'group' && !groupMembers(contact).some(member => member.title === sender)) return;
        const text = message[2].trim();
        const saved = addMessage(key, { side: 'them', sender, text, time: time || clock() });
        if (phonePopup?.isConnected) {
          const $dialog = $(phonePopup);
          const route = $dialog.data('pfViewRoute');
          if ($dialog.data('pfChatScope') === currentChatId() && route?.page === 'chat' && route.key === key) renderBubble($dialog.find('.pf-feed'), saved, contactFor(key));
        }
        created.push({ key, text });
      });
    });
    return created;
  }
  function parseMomentBlocks(blocks, time) {
    const created = [];
    blocks.forEach(block => {
      let current = null; let field = '';
      const commit = () => {
        if (!current || !current.author || !current.content) return;
        current.time = time || clock(); current.icon = '☁';
        if (current.image === '无') current.image = '';
        if (current.likes === '无') current.likes = '';
        created.push(current);
      };
      String(block).split(/\r?\n/).forEach(rawLine => {
        const line = rawLine.trim(); if (!line) return;
        const heading = line.match(/^【\s*发文者\s*[：:]\s*(.+?)\s*】$/);
        if (heading) { commit(); current = { author: heading[1].trim(), content: '', image: '', likes: '', replies: [] }; field = ''; return; }
        if (!current) return;
        const labelled = line.match(/^(内容|配图|点赞|回复)\s*[：:]\s*(.*)$/);
        if (labelled) {
          field = { 内容: 'content', 配图: 'image', 点赞: 'likes', 回复: 'replies' }[labelled[1]];
          const value = labelled[2].trim();
          if (field === 'replies') { if (value) current.replies.push(value.replace(/^-\s*/, '')); }
          else current[field] = value;
          return;
        }
        if (field === 'replies') current.replies.push(line.replace(/^-\s*/, ''));
        else if (field && line) current[field] = `${current[field] || ''}${current[field] ? '\n' : ''}${line}`;
      });
      commit();
    });
    return created;
  }
  function ingestDerivative(raw) {
    const status = parseStatusBlock(extractTopLevelBlocks(raw, 'status')[0] || '');
    const previousStatus = getStatus();
    const mergedStatus = { ...previousStatus, ...status };
    if (Object.keys(status).length) saveStatus(mergedStatus);
    const time = String(mergedStatus.time || '').trim();
    const messages = parsePhoneBlocks(extractTopLevelBlocks(raw, 'phone'), time);
    const moments = parseMomentBlocks(extractTopLevelBlocks(raw, 'moments'), time);
    moments.forEach(addMoment);
    addDerivativeHistory(raw);
    if (phonePopup && phonePopup.isConnected) updateHomeClock($(phonePopup));
    return { messages: messages.length, moments: moments.length, status: mergedStatus };
  }
  async function requestDerivative() {
    const config = getConfig();
    if (!config.proxyPreset && !String(config.apiUrl || '').trim()) throw new Error('请先在「设置」中填写副 API，或选择代理预设');
    const customApi = config.proxyPreset
      ? { proxy_preset: config.proxyPreset }
      : { apiurl: String(config.apiUrl).trim(), key: String(config.apiKey || ''), source: String(config.source || 'openai').trim() || 'openai' };
    if (String(config.model || '').trim()) customApi.model = String(config.model).trim();
    if (Number.isFinite(Number(config.temperature))) customApi.temperature = Number(config.temperature);
    if (Number.isFinite(Number(config.maxTokens)) && Number(config.maxTokens) > 0) customApi.max_tokens = Number(config.maxTokens);
    const generate = helper('generateRaw');
    if (!generate) throw new Error('未找到 generateRaw；请确认已安装并启用 Tavern Helper / JS Slash Runner');
    const status = getStatus();
    const groups = Object.values(getContacts()).filter(contact => contact.type === 'group').map(contact => ({ name: contact.title, members: ['{{user}}', ...groupMembers(contact).map(member => member.title)] }));
    const history = buildPhoneInfo() + (groups.length ? `\n<group_directory>${phoneXml(JSON.stringify(groups))}</group_directory>` : '');
    const data = getPhoneData();
    const isInitial = !Object.values(data.chats || {}).some(messages => Array.isArray(messages) && messages.length)
      && !(data.moments || []).length && !Object.keys(data.status || {}).length && !Object.keys(data.dynamicContacts || {}).length;
    const input = `<main_content>\n${mainContentForDerivative()}\n</main_content>\n\n<phone_history>\n${history || '无'}\n</phone_history>\n\n<previous_phone_status>\n以下为上次手机保存的状态，仅作为历史参考，不代表本轮最新剧情的当前状态。phone_history 中的状态与消息时间也都是历史记录。\n时间：${status.time || '未知'}\n天气：${status.weather || '未知'}\n温度：${status.temperature || '未知'}\n</previous_phone_status>`;
    const result = await runPhoneGeneration(generate, {
      should_silence: true,
      custom_api: customApi,
      ordered_prompts: [
        'world_info_before', 'persona_description', 'char_description', 'char_personality',
        'scenario', 'world_info_after', 'dialogue_examples',
        { role: 'system', content: String(config.derivativePrompt || defaultConfig.derivativePrompt) + '\n若为已有群聊生成消息，聊天名使用群名，发言人只能使用该群成员姓名，不得以群名发言，不得替{{user}}发言。' + (isInitial ? `\n\n首次输出示例：\n${initialPhoneExample}` : '') },
        'user_input',
      ],
      user_input: input + stickerPrompt() + speakingGuidelines(),
    });
    if (typeof result !== 'string') throw new Error('副 API 返回了工具调用，不是可解析的手机内容');
    return ingestDerivative(result);
  }
  function getAutoFloor() { return String(getPhoneData().autoFloor || ''); }
  function saveAutoFloor(floor) { const data = getPhoneData(); data.autoFloor = String(floor || ''); savePhoneData(data); }
  async function generateAfterMainReply(messageId, type) {
    if (!phoneScriptActive()) return;
    const config = getConfig();
    if (config.autoDerivative === false || autoGenerating || type === 'extension') return;
    if (!config.proxyPreset && !String(config.apiUrl || '').trim()) return;
    const floor = String(messageId == null ? '' : messageId);
    if (!floor || getAutoFloor() === floor) return;
    saveAutoFloor(floor);
    autoGenerating = true;
    try {
      const parsed = await requestDerivative();
      console.info(`[FloatingPhone] 楼层 ${floor} 的手机内容已更新：${parsed.messages} 条消息，${parsed.moments} 条朋友圈。`);
    } catch (error) {
      console.error('[FloatingPhone] 自动生成手机内容失败', error);
    } finally { autoGenerating = false; }
  }
  function bindAutoGeneration() {
    const on = PWin.eventOn || (typeof eventOn !== 'undefined' ? eventOn : null);
    const events = PWin.tavern_events || (typeof tavern_events !== 'undefined' ? tavern_events : null);
    if (!on || !events || !events.MESSAGE_RECEIVED) return;
    try {
      const listener = (messageId, type) => {
        const scope = currentChatId();
        const resetEpoch = getPhoneData().resetEpoch || '';
        PWin.setTimeout(() => {
          if (phoneScriptActive() && currentChatId() === scope && (getPhoneData().resetEpoch || '') === resetEpoch) generateAfterMainReply(messageId, type);
        }, 80);
      };
      const registered = on(events.MESSAGE_RECEIVED, listener);
      if (registered && typeof registered.stop === 'function') autoEventStops.push(registered.stop);
      if (events.CHAT_CHANGED) {
        const changed = on(events.CHAT_CHANGED, () => { closePhone(); });
        if (changed && typeof changed.stop === 'function') autoEventStops.push(changed.stop);
      }
    } catch (error) { console.warn('[FloatingPhone] 无法绑定正剧回复事件', error); }
  }

  function currentPrivateChatFor(key, contact) {
    const lines = [];
    let previousBucket = null;
    // 仅发送最近 50 条实际消息。按日期和上/下午分段，时间只出现在分隔线上。
    messagesFor(key).filter(message => !message.placeholder).slice(-50).forEach(message => {
      const time = bubbleTime(message);
      const bucket = time.full !== null ? `${time.timeline}:${Math.floor(time.full / (12 * 3600000))}`
        : `unknown:${time.minutes === null ? 'date' : Math.floor(time.minutes / 720)}`;
      if (bucket !== previousBucket) {
        let label = time.hhmm || time.raw || '时间未记录';
        if (time.full !== null) {
          const date = new Date(time.full);
          const pad = value => String(value).padStart(2, '0');
          label = `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${time.hhmm || '00:00'}`;
        }
        lines.push(`--- ${label} ---`);
        previousBucket = bucket;
      }
      const speaker = message.side === 'self' ? '{{user}}' : message.sender || contact.title;
      const text = String(message.text || '');
      lines.push(message.side !== 'self' && !message.sender && /^[^：:]{1,50}[：:]/.test(text) ? text : `${speaker}：${text}`);
    });
    return lines.join('\n');
  }
  function parseLatestChat(raw, names) {
    const block = String(raw || '').match(/<latest_chat\b[^>]*>([\s\S]*?)<\/latest_chat\s*>/i);
    if (!block) throw new Error('回复缺少完整的 <latest_chat> 标签，请重试');
    const escapedNames = names.map(name => String(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
    const linePattern = new RegExp(`^[ \\t]*(${escapedNames})[ \\t]*[：:][ \\t]*(.+)$`, 'gm');
    const messages = [...block[1].matchAll(linePattern)].map(match => ({ sender: match[1], text: match[2].trim() })).filter(message => message.text).slice(0, 6);
    if (!messages.length) throw new Error('回复中没有当前联系人的有效消息，请重试');
    return messages;
  }
  async function requestReply(contact, text, chatKey) {
    const speakers = contact.type === 'group' ? groupMembers(contact).map(member => member.title) : [contact.title];
    if (!speakers.length) throw new Error('群聊暂无可回复的成员');
    const instruction = contact.type === 'group'
      ? `<current_chat>内是「${contact.title}」的群聊。成员为{{user}}、${speakers.join('、')}。请根据当前话题选择合适的成员发言，合计回复1~6条消息，不必每个成员都回复。只能写名单中除{{user}}以外成员的信息，禁止替{{user}}写信息，禁止以群名发言。`
      : `<current_chat>内是目前与「${contact.title}」的消息私聊。请扮演「${contact.title}」，回复1~6条消息，只能写「${contact.title}」的信息，禁止替{{user}}写信息。`;
    const config = getConfig();
    if (!config.proxyPreset && !String(config.apiUrl || '').trim()) throw new Error('请先在「设置」中填写副 API，或选择代理预设');
    const customApi = config.proxyPreset
      ? { proxy_preset: config.proxyPreset }
      : { apiurl: String(config.apiUrl).trim(), key: String(config.apiKey || ''), source: String(config.source || 'openai').trim() || 'openai' };
    if (String(config.model || '').trim()) customApi.model = String(config.model).trim();
    if (Number.isFinite(Number(config.temperature))) customApi.temperature = Number(config.temperature);
    if (Number.isFinite(Number(config.maxTokens)) && Number(config.maxTokens) > 0) customApi.max_tokens = Number(config.maxTokens);
    const generate = helper('generateRaw');
    if (!generate) throw new Error('未找到 generateRaw；请确认已安装并启用 Tavern Helper / JS Slash Runner');
    const result = await runPhoneGeneration(generate, {
      should_silence: true,
      custom_api: customApi,
      ordered_prompts: [
        'world_info_before', 'persona_description', 'char_description', 'char_personality',
        'scenario', 'world_info_after', 'dialogue_examples',
        { role: 'system', content: String(config.systemPrompt || defaultConfig.systemPrompt) },
        ...buildRegexedHistory(), 'user_input',
      ],
      user_input: `<current_chat>\n${currentPrivateChatFor(chatKey, contact)}\n</current_chat>${stickerPrompt(speakers[0])}${speakingGuidelines()}\n\n${instruction}格式示例：\n<latest_chat>\n${speakers[0]}：新的回复内容\n${speakers[1] || speakers[0]}：新的回复内容\n</latest_chat>`,
    });
    if (typeof result !== 'string') throw new Error('副 API 返回了工具调用，不是可显示的微信文本');
    return parseLatestChat(result, speakers);
  }

  async function requestMoment(author, hint) {
    const config = getConfig();
    if (!config.proxyPreset && !String(config.apiUrl || '').trim()) throw new Error('请先在「设置」中填写副 API，或选择代理预设');
    const customApi = config.proxyPreset
      ? { proxy_preset: config.proxyPreset }
      : { apiurl: String(config.apiUrl).trim(), key: String(config.apiKey || ''), source: String(config.source || 'openai').trim() || 'openai' };
    if (String(config.model || '').trim()) customApi.model = String(config.model).trim();
    if (Number.isFinite(Number(config.temperature))) customApi.temperature = Number(config.temperature);
    if (Number.isFinite(Number(config.maxTokens)) && Number(config.maxTokens) > 0) customApi.max_tokens = Number(config.maxTokens);
    const generate = helper('generateRaw');
    if (!generate) throw new Error('未找到 generateRaw；请确认已安装并启用 Tavern Helper / JS Slash Runner');
    const result = await runPhoneGeneration(generate, {
      should_silence: true,
      custom_api: customApi,
      ordered_prompts: [
        'world_info_before', 'persona_description', 'char_description', 'char_personality',
        'scenario', 'world_info_after', 'dialogue_examples',
        { role: 'system', content: `${String(config.systemPrompt || defaultConfig.systemPrompt)}\n\n现在不是私聊，而是发布朋友圈。以「${author.title}」的身份，依据当前剧情写一条自然、简短的第一人称动态。不要写作者名、时间、动作标签、Markdown、话题标签，也不要提及提示词、API、正则或模型。` },
        ...buildRegexedHistory(), 'user_input',
      ],
      user_input: `现在要发布一条朋友圈动态。${hint ? `用户希望的方向是：${hint}` : '请根据当前剧情自行选择一个合适的生活片段或心情。'} 只输出动态正文。`,
    });
    if (typeof result !== 'string') throw new Error('副 API 返回了工具调用，不是可显示的朋友圈文本');
    return result.trim() || '……';
  }

  function bubbleTime(message) {
    const raw = String(message.recordedTime || message.time || '').trim();
    const full = parsePhoneDate(raw);
    const match = raw.match(/(?:^|\D)([01]?\d|2[0-3])[:：]([0-5]\d)(?!\d)/);
    const hhmm = match ? `${match[1].padStart(2, '0')}:${match[2]}` : '';
    return { full, hhmm, minutes: match ? Number(match[1]) * 60 + Number(match[2]) : null, raw, timeline: message.timeline || 'story' };
  }
  function renderBubbleTime($feed, message) {
    const current = bubbleTime(message);
    const previous = $feed.data('pfPreviousMessageTime');
    let gap = null;
    if (previous && current.timeline === previous.timeline) {
      if (current.full !== null && previous.full !== null) gap = current.full - previous.full;
      else if (current.full === null && previous.full === null && current.minutes !== null && previous.minutes !== null) {
        // 旧记录只有时分时，仅比较同一天内向前的时间，不猜测日期。
        const minutes = current.minutes - previous.minutes;
        if (minutes >= 0) gap = minutes * 60000;
      }
    }
    if (!previous || (gap !== null && (gap > 20 * 60000 || gap < 0)) || (gap === null && current.raw !== previous.raw)) {
      let label = current.hhmm;
      if (current.full !== null && gap !== null && (gap > 86400000 || gap < 0)) {
        const date = new Date(current.full);
        const pad = value => String(value).padStart(2, '0');
        label = `${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${current.hhmm || '00:00'}`;
        const anniversary = new Date(previous.full);
        anniversary.setUTCFullYear(anniversary.getUTCFullYear() + 1);
        if (current.full > anniversary.getTime() || gap < 0) label = `${date.getUTCFullYear()}-${label}`;
      }
      if (!label && current.full !== null) label = '00:00';
      if (label) $feed.append($('<div>').addClass('pf-time-divider').append($('<time>').text(label)));
    }
    $feed.data('pfPreviousMessageTime', current);
  }
  function speakingGuidelines() {
    return '\n\n<speaking_guidelines>\n手机互动交流指导：使用写实手机聊天风格，不必考虑怎么回复才面面俱到，也不强求总是把话说得明明白白，如通过拐弯抹角、说东答西、话里有话来暗示角色想法、而不是直接说清，都是可以的。用语可以口语化、松散、符合角色性格。甚至可以设计打错字、发错表情包之类的小失误来增加活人感。\n</speaking_guidelines>';
  }
  function stickerPrompt(speaker = '当前发言角色姓名') {
    const stickers = phoneArt.stickers || [];
    if (!stickers.length) return '';
    return `\n\n<sticker_library>\n以下是手机中可以使用的表情包库，消息中能且仅能使用以下表情包（emoji、颜文字也可以用，但不能自己凭空创造新表情包）。\n${stickers.map(sticker => sticker.token).join('\n')}\n可以单独发送表情包，也可以在文字中插入完整的表情包名（必须含扩展名）。不要输出图片网址或Markdown图片语法。用户消息里的这些文件名也代表对应的表情包。请按语境自然使用，不必每次回复都发送表情包。\n正确使用示例（放在本次要求的回复标签内）：\n${speaker}：${stickers[0].token}\n${speaker}：你好呀！${stickers[1]?.token || stickers[0].token}\n</sticker_library>`;
  }
  function stickerImage(sticker) {
    return $('<img>').attr({ src: sticker.url, alt: sticker.token, title: sticker.name, loading: 'lazy', decoding: 'async', draggable: 'false', referrerpolicy: 'no-referrer' }).addClass('pf-sticker-image').on('error', function () {
      $(this).replaceWith($('<span>').addClass('pf-sticker-fallback').text(`[表情：${sticker.name}]`));
    });
  }
  function renderMessageContent($bubble, value) {
    const text = String(value || '');
    const stickers = phoneArt.stickers || [];
    if (!stickers.length) return $bubble.text(text);
    const byToken = new Map(stickers.map(sticker => [sticker.token, sticker]));
    const pattern = new RegExp([...byToken.keys()].sort((a, b) => b.length - a.length).map(token => token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g');
    let end = 0, hasSticker = false;
    for (const match of text.matchAll(pattern)) {
      $bubble.append(PDoc.createTextNode(text.slice(end, match.index)), stickerImage(byToken.get(match[0])));
      end = match.index + match[0].length; hasSticker = true;
    }
    $bubble.append(PDoc.createTextNode(text.slice(end)));
    $bubble.toggleClass('pf-sticker-only', hasSticker && !text.replace(pattern, '').trim());
    return $bubble;
  }
  function renderBubble($feed, message, contact) {
    renderBubbleTime($feed, message);
    const $row = $('<div>').addClass('pf-msg').toggleClass('self', message.side === 'self');
    if (message.side !== 'self') {
      const sender = message.sender || contact.title;
      const key = Object.keys(getContacts()).find(key => getContacts()[key].title === sender) || sender;
      $row.append($('<i>').append(avatarElement(key, getContacts()[key] || contact)));
    }
    const $bubble = renderMessageContent($('<span>'), message.text);
    if (contact.type === 'group' && message.side !== 'self') $row.append($('<div>').addClass('pf-group-bubble').append($('<b>').addClass('pf-group-sender').text(message.sender || '群成员'), $bubble));
    else $row.append($bubble);
    $feed.append($row);
    $feed.scrollTop($feed.prop('scrollHeight'));
  }
  function phoneViewState($dialog) {
    const scope = $dialog.data('pfChatScope') || currentChatId();
    if (!phoneViewStates.has(scope)) phoneViewStates.set(scope, { last: { page: 'home' }, apps: {} });
    return phoneViewStates.get(scope);
  }
  function rememberPhoneView($dialog) {
    const route = $dialog.data('pfViewRoute');
    if (!route) return;
    const snapshot = { ...route, scroll: {}, drafts: {} };
    const $screen = $dialog.find('.pfphone-screen');
    ['.pf-home', '.pf-list', '.pf-feed', '.pf-moment-scroll', '.pf-smain'].forEach(selector => {
      const element = $screen.find(selector)[0];
      if (element) snapshot.scroll[selector] = element.scrollTop;
    });
    ['[data-pf-input]', '[data-pf-moment-hint]'].forEach(selector => {
      const element = $screen.find(selector)[0];
      if (element) snapshot.drafts[selector] = element.value;
    });
    const state = phoneViewState($dialog);
    state.last = snapshot;
    if (route.page !== 'home') state.apps[route.page === 'settings' ? 'settings' : 'wechat'] = snapshot;
  }
  function enterPhoneView($dialog, page, key) {
    rememberPhoneView($dialog);
    $dialog.data('pfViewRoute', { page, key });
    if (page !== 'home') $dialog.data('pfActiveApp', page === 'settings' ? 'settings' : 'wechat');
  }
  function restorePhoneView($dialog, snapshot) {
    const saved = snapshot || { page: 'home' };
    if (saved.page === 'chat') renderChat($dialog, saved.key);
    else if (saved.page === 'moments') renderMoments($dialog);
    else if (saved.page === 'composer') renderMomentComposer($dialog);
    else if (saved.page === 'wechat') renderWeChat($dialog);
    else if (saved.page === 'settings') renderSettings($dialog);
    else if (saved.page === 'contacts') renderContactCreator($dialog);
    else if (saved.page === 'group-create') renderContactCreator($dialog, true);
    else renderHome($dialog);
    const restore = () => {
      const route = $dialog.data('pfViewRoute');
      if (!$dialog[0].isConnected || route?.page !== saved.page || route?.key !== saved.key) return;
      const $screen = $dialog.find('.pfphone-screen');
      Object.entries(saved.scroll || {}).forEach(([selector, top]) => $screen.find(selector).scrollTop(top));
    };
    Object.entries(saved.drafts || {}).forEach(([selector, value]) => $dialog.find('.pfphone-screen').find(selector).val(value));
    restore();
    // 聊天页原本会在下一帧滚到底部，此处随后恢复用户离开的位置。
    PWin.setTimeout(restore, 0);
  }
  function phoneMotionEnabled() {
    return !PWin.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }
  function appIconTransform($screen, icon) {
    const screen = $screen[0];
    const bounds = screen.getBoundingClientRect();
    const target = icon.getBoundingClientRect();
    return `translate(${target.left - bounds.left - screen.clientLeft}px, ${target.top - bounds.top - screen.clientTop}px) scale(${target.width / screen.clientWidth}, ${target.height / screen.clientHeight})`;
  }
  function decorateMotionClone($clone) {
    $clone.attr({ 'aria-hidden': 'true', inert: '' }).addClass('pf-motion-layer');
    $clone.find('[id]').removeAttr('id');
    $clone.removeAttr('id');
    return $clone;
  }
  function openPhoneApp($dialog, app, icon) {
    if ($dialog.data('pfAppTransition')) return;
    const render = app === 'wechat' ? renderWeChat : app === 'settings' ? renderSettings : null;
    if (!render) return;
    const $screen = $dialog.find('.pfphone-screen');
    const animate = phoneMotionEnabled() && typeof $screen[0].animate === 'function' && icon;
    const from = animate ? appIconTransform($screen, icon) : '';
    const $desktop = animate ? decorateMotionClone($('<div>').append($screen.children().clone(false))).addClass('pf-motion-desktop') : null;
    $dialog.data('pfActiveApp', app);
    const saved = phoneViewState($dialog).apps[app];
    if (saved) restorePhoneView($dialog, saved);
    else render($dialog);
    if (!animate) return;
    const $app = $screen.children().first().addClass('pf-app-opening');
    $screen.prepend($desktop).addClass('pf-screen-transition');
    $dialog.data('pfAppTransition', true);
    const animation = $app[0].animate([
      { transform: from, opacity: .25, borderRadius: '40px' },
      { transform: 'translate(0, 0) scale(1, 1)', opacity: 1, borderRadius: '18px' },
    ], { duration: 390, easing: 'cubic-bezier(.2,.85,.25,1)', fill: 'both' });
    animation.finished.catch(() => {}).finally(() => {
      animation.cancel();
      $desktop.remove();
      $app.removeClass('pf-app-opening');
      $screen.removeClass('pf-screen-transition');
      $dialog.removeData('pfAppTransition');
    });
  }
  function returnPhoneHome($dialog) {
    if ($dialog.data('pfAppTransition')) return;
    const app = $dialog.data('pfActiveApp');
    const $screen = $dialog.find('.pfphone-screen');
    if (!app || !phoneMotionEnabled() || typeof $screen[0].animate !== 'function') { renderHome($dialog); return; }
    const $original = $screen.children().first();
    const scrollPositions = $original.find('*').addBack().toArray().map(element => [element.scrollLeft, element.scrollTop]);
    const $snapshot = decorateMotionClone($original.clone(false));
    renderHome($dialog);
    const icon = $screen.find(`[data-pf-app="${app}"] .pf-app-art`)[0];
    if (!icon) return;
    const to = appIconTransform($screen, icon);
    $screen.append($snapshot).addClass('pf-screen-transition');
    $snapshot.find('*').addBack().each((index, element) => {
      const position = scrollPositions[index];
      if (position) { element.scrollLeft = position[0]; element.scrollTop = position[1]; }
    });
    $dialog.data('pfAppTransition', true);
    const animation = $snapshot[0].animate([
      { transform: 'translate(0, 0) scale(1, 1)', opacity: 1, borderRadius: '18px', offset: 0 },
      { opacity: .9, offset: .65 },
      { transform: to, opacity: 0, borderRadius: '40px', offset: 1 },
    ], { duration: 330, easing: 'cubic-bezier(.4,0,.2,1)', fill: 'both' });
    animation.finished.catch(() => {}).finally(() => {
      animation.cancel();
      $snapshot.remove();
      $screen.removeClass('pf-screen-transition');
      $dialog.removeData('pfAppTransition');
    });
  }
  function renderHome($dialog) {
    enterPhoneView($dialog, 'home');
    $dialog.removeData('pfActiveApp');
    $dialog.find('.pfphone-screen').html(`<div class="pf-top"><time class="pf-status-time"></time><img class="pf-status-art" src="${phoneArt.status}" alt=""></div><main class="pf-home"><div class="pf-clock"><time class="pf-clock-time"></time><div class="pf-clock-date"></div><div class="pf-clock-weather" hidden></div></div><div class="pf-apps"><button class="pf-app" type="button" data-pf-app="wechat" aria-label="打开微信消息"><img class="pf-app-art" src="${phoneArt.message}" alt="" draggable="false"><span>消息</span></button><button class="pf-app" type="button" data-pf-app="settings" aria-label="打开设置"><img class="pf-app-art" src="${phoneArt.settings}" alt="" draggable="false"><span>设置</span></button></div></main>`);
    updateHomeClock($dialog);
    $dialog.off('.pokemonFloatingPhone');
    $dialog.on('click.pokemonFloatingPhone', '[data-pf-app]', function () {
      const app = $(this).attr('data-pf-app');
      openPhoneApp($dialog, app, $(this).find('.pf-app-art')[0]);
    });
  }
  // 仅显示剧情时间；尚未建立时间时保持空白占位，不引入现实日期。
  function updateHomeClock($dialog) {
    const status = getStatus();
    const raw = String(status.time || '').trim();
    const match = raw.match(/(?:^|\D)([01]?\d|2[0-3])[:：]([0-5]\d)(?!\d)/);
    const time = match ? `${match[1].padStart(2, '0')}:${match[2]}` : '··:··';
    let date = raw ? raw.replace(/(?:[01]?\d|2[0-3])[:：][0-5]\d(?::[0-5]\d)?/, '').trim() : '';
    const parts = raw.match(/(\d{4})[年/.-](\d{1,2})[月/.-](\d{1,2})日?/);
    const calendar = parts ? new Date(Number(parts[1]), Number(parts[2]) - 1, Number(parts[3])) : null;
    if (calendar) date = `${calendar.toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase()} · ${calendar.toLocaleDateString('en-US', { month: 'short' })} ${calendar.getDate()}`;
    $dialog.find('.pf-clock-time,.pf-status-time').text(time);
    $dialog.find('.pf-message-status time').text(time);
    $dialog.find('.pf-clock-date').text(date).attr('title', raw);
    const weather = [status.weather, status.temperature].filter(Boolean).join(' · ');
    $dialog.find('.pf-clock-weather').text(weather).prop('hidden', !weather);
  }
  function avatarFor(key, contact) {
    const avatars = phoneArt.avatars || {};
    const names = Object.keys(avatars);
    const defaults = { friend: '苹果猫头鹰', roommate: '柯基', editor: '山雀' };
    let hash = 0;
    for (const char of String(key)) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
    return avatars[contact.avatar || defaults[key]] || avatars[names[hash % names.length]] || '';
  }
  function avatarElement(key, contact) {
    return $('<img alt="" draggable="false">').addClass('pf-contact-art').attr('src', avatarFor(key, contact));
  }
  function unreadCount(key) {
    const chats = getChats();
    const count = messages => Array.isArray(messages) ? messages.filter(message => message.unread === true && message.side !== 'self' && !message.placeholder).length : 0;
    return key ? count(chats[key]) : Object.values(chats).reduce((sum, messages) => sum + count(messages), 0);
  }
